const items = $input.all();
const webhookData = $("Webhook1").first();
const body = webhookData.json.body || webhookData.json || {};
const atts = body.attachments || [];

for (const item of items) {
  if (atts.length > 0) {
    item.binary = {};
    for (let i = 0; i < atts.length; i++) {
      const key = "attachment_" + i;
      item.binary[key] = {
        data: atts[i].data,
        mimeType: atts[i].mimeType || "application/octet-stream",
        fileName: atts[i].fileName || "file_" + i
      };
    }
    item.json.hasAttachments = true;
    item.json.binaryKeys = Object.keys(item.binary).join(",");
  } else {
    item.json.hasAttachments = false;
    item.json.binaryKeys = "";
  }
}
return items;
